    "name": "MATH.H",
    "contents": "#ifndef __MATH_H\n#define __MATH_H\n\n// æ°å­¦ã®é¢æ°ï¼libc/math.cï¼ãlong double ã¯ double ã¨åã\n\n#define HUGE_VAL (1.0 / 0.0)\n#define HUGE_VALF (1.0f / 0.0f)\n#define HUGE_VALL (1.0L / 0.0L)\n#define INFINITY (1.0f / 0.0f)\n#define NAN (0.0f / 0.0f)\n\n#define M_E 2.7182818284590452354\n#define M_LOG2E 1.4426950408889634074\n#define M_LOG10E 0.43429448190325182765\n#define M_LN2 0.69314718055994530942\n#define M_LN10 2.30258509299404568402\n#define M_PI 3.14159265358979323846\n#define M_PI_2 1.57079632679489661923\n#define M_PI_4 0.78539816339744830962\n#define M_1_PI 0.31830988618379067154\n#define M_2_PI 0.63661977236758134308\n#define M_2_SQRTPI 1.12837916709551257390\n#define M_SQRT2 1.41421356237309504880\n#define M_SQRT1_2 0.70710678118654752440\n\n#define FP_NAN 0\n#define FP_INFINITE 1\n#define FP_ZERO 2\n#define FP_SUBNORMAL 3\n#define FP_NORMAL 4\n\nint __mycpu_signbit(double x);\nint __mycpu_isinf(double x);\nint __mycpu_isnan(double x);\nint __mycpu_isfinite(double x);\n\n#define isnan(x) __mycpu_isnan(x)\n#define isinf(x) __mycpu_isinf(x)\n#define isfinite(x) __mycpu_isfinite(x)\n#define signbit(x) __mycpu_signbit(x)\n#define isnormal(x) (fpclassify(x) == FP_NORMAL)\n#define fpclassify(x) __mycpu_fpclassify(x)\nstatic inline int __mycpu_fpclassify(double x) {\n  if (x != x) return FP_NAN;\n  if (__mycpu_isinf(x)) return FP_INFINITE;\n  if (x == 0) return FP_ZERO;\n  return (x < 0 ? -x : x) < 2.2250738585072014e-308 ? FP_SUBNORMAL : FP_NORMAL;\n}\n#define isgreater(x, y) ((x) > (y))\n#define isgreaterequal(x, y) ((x) >= (y))\n#define isless(x, y) ((x) < (y))\n#define islessequal(x, y) ((x) <= (y))\n#define isunordered(x, y) ((x) != (x) || (y) != (y))\n\ndouble fabs(double x);\ndouble copysign(double x, double y);\ndouble trunc(double x);\ndouble floor(double x);\ndouble ceil(double x);\ndouble round(double x);\ndouble nearbyint(double x);\ndouble rint(double x);\nlong lround(double x);\nlong lrint(double x);\ndouble modf(double x, double *ip);\ndouble ldexp(double x, int n);\ndouble scalbn(double x, int n);\ndouble frexp(double x, int *ep);\ndouble sqrt(double x);\ndouble fmod(double x, double y);\ndouble remainder(double x, double y);\ndouble exp(double x);\ndouble exp2(double x);\ndouble expm1(double x);\ndouble log(double x);\ndouble log10(double x);\ndouble log2(double x);\ndouble log1p(double x);\ndouble pow(double x, double y);\ndouble cbrt(double x);\ndouble hypot(double x, double y);\ndouble sin(double x);\ndouble cos(double x);\ndouble tan(double x);\ndouble asin(double x);\ndouble acos(double x);\ndouble atan(double x);\ndouble atan2(double y, double x);\ndouble sinh(double x);\ndouble cosh(double x);\ndouble tanh(double x);\ndouble asinh(double x);\ndouble acosh(double x);\ndouble atanh(double x);\ndouble fmax(double x, double y);\ndouble fmin(double x, double y);\ndouble fdim(double x, double y);\ndouble fma(double x, double y, double z);\n\nfloat fabsf(float x);\nfloat sqrtf(float x);\nfloat floorf(float x);\nfloat ceilf(float x);\nfloat truncf(float x);\nfloat roundf(float x);\nfloat fmodf(float x, float y);\nfloat expf(float x);\nfloat logf(float x);\nfloat log10f(float x);\nfloat log2f(float x);\nfloat powf(float x, float y);\nfloat sinf(float x);\nfloat cosf(float x);\nfloat tanf(float x);\nfloat atanf(float x);\nfloat atan2f(float y, float x);\nfloat asinf(float x);\nfloat acosf(float x);\nfloat sinhf(float x);\nfloat coshf(float x);\nfloat tanhf(float x);\nfloat hypotf(float x, float y);\nfloat cbrtf(float x);\nfloat ldexpf(float x, int n);\nfloat frexpf(float x, int *e);\nfloat copysignf(float x, float y);\nfloat fmaxf(float x, float y);\nfloat fminf(float x, float y);\n\n// long double ã®çã¯ double ã¨åã\n#define fabsl fabs\n#define sqrtl sqrt\n#define floorl floor\n#define ceill ceil\n#define truncl trunc\n#define roundl round\n#define fmodl fmod\n#define expl exp\n#define logl log\n#define log10l log10\n#define powl pow\n#define sinl sin\n#define cosl cos\n#define tanl tan\n#define atanl atan\n#define atan2l atan2\n#define ldexpl ldexp\n#define frexpl frexp\n#define modfl modf\n#define copysignl copysign\n\n#endif\n"
